css:
/* Layout for this component's own nodes.
   These were per-node `styles` overrides. Past a certain number of them in
   one document the browser stops matching the compiled
   [data-bz-node="x"][data-bz-node] rules — some apply and some silently do
   not — so the same declarations live here instead, where they hold. See the
   note in the commit message; this is a platform bug worth fixing upstream.
   ------------------------------------------------------------------------- */
[data-bz-node="featured-band"]{padding-top:120px;padding-bottom:0px}
@media (max-width: 640px){
[data-bz-node="featured-band"]{padding-top:64px}
}

/* ------------------------------------------------------- FEATURED LISTINGS ---
   A card is a bordered column: photo at 4:3, then copy, with price and CTA
   pushed to the foot by margin-top:auto so every card in the row lines up. */

[data-bz-node="featured-band"] .bz-block { padding-block: 0; }
.bz-block[data-bz-node="featured-heading"] p.bz-eyebrow { margin: 0 0 14px; }
[data-bz-node="featured-heading"] h2 { margin: 0 0 44px; }

[data-bz-node="featured-grid-row"] > .bz-col {
  display: flex;
  flex-direction: column;
  background: var(--card);
  border: 1px solid var(--line);
}
[data-bz-node="featured-grid-row"] > .bz-col .bz-block--image img {
  aspect-ratio: 4 / 3;
  width: 100%;
  object-fit: cover;
  object-position: center;
  display: block;
}

/* Everything below the photograph shares the card's 20px inset. */
[data-bz-node="featured-grid-row"] > .bz-col > .bz-block:not(.bz-block--image) { padding-inline: 20px; }
[data-bz-node="featured-grid-row"] > .bz-col > .bz-block--heading { margin-top: 20px; }
[data-bz-node="featured-grid-row"] > .bz-col > .bz-block--buttons { padding-bottom: 20px; }

[data-bz-node="featured-grid-row"] > .bz-col .bz-block--heading h3 {
  font: 700 17px / 1.3 var(--font-heading);
  margin: 0 0 4px;
}
[data-bz-node="featured-grid-row"] > .bz-col > .bz-block:nth-child(3) p {
  font-size: 13px;
  line-height: 1.6;
  color: var(--muted);
  margin: 0 0 14px;
}
[data-bz-node="featured-grid-row"] > .bz-col .bz-text,
[data-bz-node="featured-grid-row"] > .bz-col .bz-headingblock { max-width: none; }

.ss-specs { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 18px; }
.ss-chip {
  font: 400 12px / 1.6 var(--font-body);
  border: 1px solid var(--line);
  /* 6px is intentional even in the hard-edged theme — the handoff keeps spec
     chips soft. */
  border-radius: 6px;
  padding: 6px 10px;
  color: #242424;
}
.ss-chip strong { font-weight: 700; }

/* The price is the first thing at the foot, so the spacer lands above it. */
[data-bz-node="featured-grid-row"] > .bz-col > .bz-block:nth-child(5) { margin-top: auto; }
[data-bz-node="featured-grid-row"] > .bz-col > .bz-block:nth-child(5) p {
  font: 800 22px / 1.6 var(--font-heading);
  color: #242424;
  margin: 0 0 2px;
}
[data-bz-node="featured-grid-row"] > .bz-col > .bz-block:nth-child(6) p {
  font: 700 12px / 1.6 var(--font-body);
  color: var(--accent);
  margin: 0 0 16px;
}
[data-bz-node="featured-grid-row"] > .bz-col .bz-block--buttons .bz-btn {
  width: 100%;
  font-size: 13px;
  letter-spacing: 0.04em;
  /* 10px, as the handoff has it for this one button. */
  border-radius: 10px;
}

[data-bz-node="featured-cta-row"] { margin-top: 28px; }
[data-bz-node="featured-cta"] .bz-btns { justify-content: flex-end; }
[data-bz-node="featured-cta"] .bz-btn { padding: 4px 0; font: 700 var(--text-small) / 1.6 var(--font-body); text-decoration: none; }
